import json,struct,collections,pathlib
D=pathlib.Path('/private/tmp/tsgolint-diagnostic-investigation')
def load(p):
 a=[]
 with open(p,'rb') as f:
  while h:=f.read(5):
   n,k=struct.unpack('<IB',h);v=json.loads(f.read(n))
   if k==1:a.append(v)
 return a
def groups(a):
 d=collections.defaultdict(list)
 for v in a:d[(v.get('rule','<compiler>'),v['file_path'])].append(v)
 return d
def compare(r,g,name):
 key=lambda v:json.dumps(v,sort_keys=True,separators=(',',':'))
 rc=collections.Counter(map(key,r));gc=collections.Counter(map(key,g));out=[];counts=collections.defaultdict(collections.Counter)
 for value,n in (rc&gc).items():counts[json.loads(value).get('rule','<compiler>')]['exact']+=n
 R=groups([json.loads(v) for v,n in (rc-gc).items() for _ in range(n)])
 G=groups([json.loads(v) for v,n in (gc-rc).items() for _ in range(n)])
 for k in sorted(R.keys()|G.keys()):
  a=R[k];b=G[k];used=set()
  for v in a:
   p=v['range'];cand=[]
   for i,w in enumerate(b):
    if i in used:continue
    q=w['range']; same=p==q
    compatible=v['message'].get('id')==w['message'].get('id') or k[0]=='no-deprecated'
    overlap=max(p['pos'],q['pos'])<min(p['end'],q['end'])
    if same or compatible and overlap:cand.append((not same,abs(p['pos']-q['pos'])+abs(p['end']-q['end']),i))
   if cand:
    i=min(cand)[2];used.add(i);w=b[i]
    if v==w:cat='exact'
    elif v['range']!=w['range']:cat='range_and_or_metadata'
    else:cat='metadata_only'
   else:cat='rust_only';w=None
   counts[k[0]][cat]+=1
   if cat!='exact':out.append({'category':cat,'rust':v,'go':w})
  for i,w in enumerate(b):
   if i not in used:counts[k[0]]['go_only']+=1;out.append({'category':'go_only','rust':None,'go':w})
 (D/f'{name}.json').write_text(json.dumps({'counts':counts,'diffs':out},indent=2))
 print(name)
 for k,v in counts.items():
  if set(v)!={'exact'}:print(k,dict(v))
 return counts
if __name__=='__main__':
 B=pathlib.Path('/private/tmp/tsrs-lint-parallel-load-final-1')
 r=load(B/'lint-default-0-after.out');g=load(B/'lint-default-0-go.out')
 compare(r,g,'installed-comparison')
 p=D/'pinned-go.out'
 if p.exists() and p.stat().st_size>1000000:compare(r,load(p),'pinned-comparison')
 compare(load(B/'lint-typecheck-default-0-after.out'),load(B/'lint-typecheck-default-0-go.out'),'full-comparison')

